import React,{useState} from 'react';
import {Text} from 'react-native';
export function Icon({name,color}:{name:string;color?:string}){return <Text aria-hidden style={{color,fontSize:20}}>{name.includes('calendar')?'▦':name.includes('construct')?'⚒':name.includes('close')?'⊗':name.includes('checkmark')?'✓':'◈'}</Text>;}
const p='11111111-1111-4111-8111-111111111111',id='22222222-2222-4222-8222-222222222222',r='33333333-3333-4333-8333-333333333333';
const area={id,propertyId:p,requestId:r,name:'Kapalı halı saha',type:'SPORTS_COURT',buildingId:null,visibility:'PROPERTY',usage:'RESERVATION',capacity:14,description:'Site sakinlerinin ortak spor alanı.',rules:'Spor ayakkabısı ile girilir.',opensAt:'08:00',closesAt:'22:00',feeAmount:'0.00',currency:'TRY',isEnabled:true,version:1,createdAt:'2026-10-26T12:00:00Z',modifiedAt:'2026-10-26T12:00:00Z',replayed:false};
let offline=false,manager=false;
export function FixtureControls(){const [,tick]=useState(0);return <div style={{display:'flex',gap:8,padding:12}}><button onClick={()=>{offline=!offline;tick(n=>n+1);window.dispatchEvent(new Event('fixture-change'));}}>Bağlantıyı değiştir</button><button onClick={()=>{manager=!manager;tick(n=>n+1);window.dispatchEvent(new Event('fixture-change'));}}>Rolü değiştir</button></div>;}
export function useAuth(){const [,tick]=useState(0);React.useEffect(()=>{const listener=()=>tick(n=>n+1);window.addEventListener('fixture-change',listener);return()=>window.removeEventListener('fixture-change',listener);},[]);const selected={propertyId:p,propertyName:'BuildingFlow Test Sitesi',unitId:manager?null:id,unitNumber:manager?null:'12',role:manager?'MANAGER':'RESIDENT',...(manager?{}:{canonical:{kind:'RESIDENT',id:r,tenantId:p}})};return{selected,session:{userId:'fixture'},offline,commonAreaCache:async()=>null,commonAreaRequest:async(url:string,method='GET',body?:unknown)=>{if(offline)throw Error();const u=new URL(url,'http://fixture');let value:unknown;if(u.pathname.endsWith('/schedule'))value={commonAreaId:id,date:u.searchParams.get('date'),opensAt:'08:00',closesAt:'22:00',capacity:14,reservable:true,busy:[{startsAt:'10:00',endsAt:'12:00',state:'CLOSED',reserved:0},{startsAt:'14:00',endsAt:'15:00',state:'FULL',reserved:14}]};else if(u.pathname.endsWith('/reservations')){if(method==='POST')return new Response('{}',{status:409});value={items:[],totalCount:0,page:1,pageSize:20};}else value={items:[area],page:1,pageSize:12,totalCount:1};return new Response(JSON.stringify(value),{status:200});}};}
export const randomUUID=()=>crypto.randomUUID();
